                if (confirm) apply(confirm)
                setConfirm(null)
              }}
            >
              {confirm?.kind === "new" ? "Start new" : "Clear conversation"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </TooltipProvider>
  )
}

